package app.taketray.ui.theme

import androidx.compose.foundation.isSystemInDarkTheme
import androidx.compose.material3.MaterialTheme
import androidx.compose.runtime.Composable
import androidx.compose.runtime.CompositionLocalProvider

/**
 * Brand colours are fixed (no dynamic colour) so reels, chips and the
 * "clips waiting" marigold look the same on every phone.
 */
@Composable
fun TakeTrayTheme(
    darkTheme: Boolean = isSystemInDarkTheme(),
    content: @Composable () -> Unit,
) {
    val extended = if (darkTheme) DarkExtendedColors else LightExtendedColors
    CompositionLocalProvider(LocalExtendedColors provides extended) {
        MaterialTheme(
            colorScheme = if (darkTheme) DarkColors else LightColors,
            typography = AppTypography,
            shapes = AppShapes,
            content = content,
        )
    }
}

/** Wrap the tag player and clip viewer so they are always dark. */
@Composable
fun VideoTheme(content: @Composable () -> Unit) =
    TakeTrayTheme(darkTheme = true, content = content)
